// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // transfer ownership to the test contract's caller (itself, the deployer) is already valid;
        // hand ownership to a fresh fuzzed actor first, then have that actor set a new owner.
        address actor = address(uint160(uint256(keccak256(abi.encodePacked(newOwner, uint256(1))))) | uint160(1));
        vm.prank(address(this));
        c.setOwner(actor);
        vm.prank(actor);
        c.setOwner(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}
